INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description") VALUES ('ee7266d7-bf04-522e-82c3-67e925060fa5', 'catalog-import:logbar', 'CATALOG-LOGBAR', 'Logbar Domy', 'PL', NULL, 0, 'szkielet-drewniany', 'not_submitted', '2026-10-09T06:28:10.142Z'::timestamptz, '2026-10-09T07:04:49.716Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Producent domów całorocznych z drewna konstrukcyjnego klasy C24 w technologii szkieletowej, z wnętrzami wykończonymi deską boazeryjną lub płytą G-K. Oferta obejmuje domy parterowe, z poddaszem lub antresolą o powierzchni zabudowy od 35 do 110 m², także z tarasem lub patio. Na całość domu producent udziela gwarancji 24 miesiące, a na konstrukcję 10 lat.') ON CONFLICT DO NOTHING;
INSERT INTO "producer_delivery_country" ("producer_id", "country_code", "created_at") VALUES ('ee7266d7-bf04-522e-82c3-67e925060fa5', 'PL', '2026-10-09T06:28:10.142Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('2297c8d5-601f-4e05-92e1-eb77fea2b533', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'catalog-import:logbar', NULL, '2026-10-09T06:28:10.142Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('00fe5523-11f5-452c-8bb8-697e21e45cf5', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'en', 'Producer of year-round houses built from C24 structural timber in a timber-frame technology, with interiors finished in tongue-and-groove boards or plasterboard. The range covers single-storey houses and houses with an attic or mezzanine, with a footprint from 35 to 110 m², some with a terrace or patio. The producer gives a 24-month warranty on the whole house and 10 years on the structure.', NULL, NULL, '2026-10-09T06:28:10.142Z'::timestamptz, '2026-10-09T07:04:49.716Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('b1fceb12-c3be-4200-a124-4039d6826a1d', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'de', 'Hersteller von Ganzjahreshäusern aus Konstruktionsholz der Klasse C24 in Holzrahmenbauweise, mit Innenräumen aus Profilholz oder Gipskartonplatten. Das Angebot umfasst eingeschossige Häuser sowie Häuser mit Dachgeschoss oder Galerie mit einer Grundfläche von 35 bis 110 m², teils mit Terrasse oder Patio. Der Hersteller gibt 24 Monate Garantie auf das gesamte Haus und 10 Jahre auf die Konstruktion.', NULL, NULL, '2026-10-09T06:28:10.142Z'::timestamptz, '2026-10-09T07:04:49.716Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('d48c52e8-b711-436e-88bc-93f59697d7d9', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'nl', 'Producent van huizen voor het hele jaar van constructiehout klasse C24 in houtskeletbouw, met een interieur afgewerkt met profielplanken of gipsplaten. Het aanbod omvat huizen van één bouwlaag en huizen met zolder of mezzanine met een bebouwde oppervlakte van 35 tot 110 m², deels met terras of patio. De producent geeft 24 maanden garantie op het hele huis en 10 jaar op de constructie.', NULL, NULL, '2026-10-09T06:28:10.142Z'::timestamptz, '2026-10-09T07:04:49.716Z'::timestamptz) ON CONFLICT DO NOTHING;
